import React, { useCallback, useEffect, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import './styles.css';

type Page = 'library' | 'activity' | 'connections' | 'settings';
type Study = { studyUid: string; patientKey: string; patientName: string; patientId: string; studyDate: string; studyDescription: string; modalities: string[]; seriesCount: number; instanceCount: number; bytes: number };
type Series = { seriesUid: string; studyUid: string; seriesDescription: string; modality: string; seriesNumber: number; instanceCount: number; frames: number; bytes: number };
type Instance = { id: string; studyUid: string; seriesUid: string; sopUid: string; instanceNumber: number; frames: number; rows: number; columns: number; bytes: number; transferSyntaxUid: string; modality: string; sha256: string };
type Summary = { patients: number; studies: number; series: number; instances: number; bytes: number };
type Session = { authenticated: boolean; setupRequired: boolean; bootstrapRequired?: boolean };
type ViewerRequest = { study: Study; series: Series; instances: Instance[]; index: number; wholeSeries?: boolean };
type IconName = 'library' | 'activity' | 'connections' | 'settings' | 'upload' | 'search' | 'arrow' | 'chevron' | 'close' | 'check' | 'copy' | 'shield' | 'folder' | 'image' | 'database' | 'logout' | 'refresh' | 'external' | 'patient' | 'play' | 'info' | 'menu' | 'download' | 'file' | 'spark';

