function Icon({ name, size = 20, className = '' }: { name: IconName; size?: number; className?: string }) {
  return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" className={className} aria-hidden="true"><path d={iconPaths[name]} /></svg>;
}

function Logo({ compact = false }: { compact?: boolean }) {
  return <div className="brand"><svg className="brand-mark" width="29" height="30" viewBox="0 0 29 30" fill="none" aria-hidden="true"><rect x="1" y="3" width="27" height="5" rx="1" fill="currentColor"/><rect x="1" y="13" width="20" height="5" rx="1" fill="currentColor"/><rect x="1" y="23" width="27" height="5" rx="1" fill="currentColor"/></svg>{!compact && <span><strong>EASI</strong> <span className="brand-light">Store</span></span>}</div>;
}

function Spinner({ label = 'Loading' }: { label?: string }) { return <span className="spinner" role="status" aria-label={label} />; }
function count(value: number | undefined) { return new Intl.NumberFormat().format(Number(value) || 0); }
function bytes(value: number | undefined) { const n = Number(value) || 0; if (n < 1024) return `${n} B`; const i = Math.min(Math.floor(Math.log(n) / Math.log(1024)), 4); return `${(n / 1024 ** i).toFixed(i > 1 ? 1 : 0)} ${['B', 'KiB', 'MiB', 'GiB', 'TiB'][i]}`; }
function person(value: string | undefined) { return value?.replace(/\^+/g, ' ').trim() || 'Unidentified patient'; }
function date(value: string | undefined) {
  if (!value) return 'Date unavailable';
  const parsed = /^\d{8}$/.test(value) ? new Date(`${value.slice(0, 4)}-${value.slice(4, 6)}-${value.slice(6, 8)}T12:00:00Z`) : new Date(value);
  return Number.isNaN(parsed.getTime()) ? value : parsed.toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: 'numeric', timeZone: 'UTC' });
}
function errorMessage(error: unknown) { return error instanceof Error ? error.message : 'Something went wrong. Please try again.'; }
function downloadPath(instance: Instance) { return `/api/v1/download/${encodeURIComponent(instance.studyUid)}/${encodeURIComponent(instance.seriesUid)}/${encodeURIComponent(instance.sopUid)}`; }

async function api<T = any>(path: string, options: RequestInit = {}): Promise<T> {
  const method = options.method || 'GET';
  const headers = new Headers(options.headers);
  if (method !== 'GET' && method !== 'HEAD') headers.set('X-EASI-Store', '1');
  if (typeof options.body === 'string') headers.set('Content-Type', 'application/json');
  const response = await fetch(`/api/v1${path}`, { ...options, headers, credentials: 'same-origin' });
  const result = await response.json().catch(() => null);
  if (!response.ok) {
    if (response.status === 401 && !['/login', '/setup', '/session'].includes(path)) window.dispatchEvent(new Event('easi-session-expired'));
    throw Object.assign(new Error(result?.error?.message || result?.message || `The request failed (${response.status}).`), { status: response.status });
  }
  return result as T;
}

function Modal({ title, eyebrow, children, footer, onClose, busy = false, className = '' }: { title: string; eyebrow?: string; children: React.ReactNode; footer?: React.ReactNode; onClose: () => void; busy?: boolean; className?: string }) {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const previous = document.activeElement as HTMLElement | null;
    const modal = ref.current;
    const focusables = () => [...(modal?.querySelectorAll<HTMLElement>('button:not(:disabled), input:not(:disabled), select:not(:disabled), a[href], [tabindex="0"]') || [])].filter(item => item.getClientRects().length);
    (focusables()[0] || modal)?.focus();
    const keydown = (event: KeyboardEvent) => {
      if (event.key === 'Escape' && !busy) onClose();
      if (event.key === 'Tab') {
        const items = focusables(); const first = items[0]; const last = items[items.length - 1];
        if (!items.length) { event.preventDefault(); modal?.focus(); }
        else if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
        else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
      }
    };
    const overflow = document.body.style.overflow; document.body.style.overflow = 'hidden';
    document.addEventListener('keydown', keydown);
    return () => { document.removeEventListener('keydown', keydown); document.body.style.overflow = overflow; previous?.focus(); };
  }, [busy, onClose]);
  return <div className="modal-backdrop" onMouseDown={event => { if (event.target === event.currentTarget && !busy) onClose(); }}><div className={`modal ${className}`} ref={ref} role="dialog" aria-modal="true" aria-label={title} tabIndex={-1}><header className="modal-heading"><div>{eyebrow && <div className="eyebrow">{eyebrow}</div>}<h2>{title}</h2></div><button className="icon-button" aria-label="Close dialog" onClick={onClose} disabled={busy}><Icon name="close" /></button></header><div className="modal-body">{children}</div>{footer && <footer className="modal-footer">{footer}</footer>}</div></div>;
}

function AuthScreen({ session, onAuthenticated }: { session: Session; onAuthenticated: () => void }) {
  const [username, setUsername] = useState(''); const [password, setPassword] = useState(''); const [confirm, setConfirm] = useState(''); const [bootstrapToken, setBootstrapToken] = useState(''); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  const setup = session.setupRequired;
  async function submit(event: React.FormEvent) {
    event.preventDefault(); setError('');
    if (setup && password !== confirm) { setError('The passwords do not match.'); return; }
    setBusy(true);
    try { await api(setup ? '/setup' : '/login', { method: 'POST', body: JSON.stringify({ username, password, ...(setup && bootstrapToken ? { bootstrapToken } : {}) }) }); onAuthenticated(); }
    catch (e) { setError(errorMessage(e)); } finally { setBusy(false); }
  }
  return <main className="auth-page"><div className="auth-decoration" aria-hidden="true"><div className="orbit orbit-one"/><div className="orbit orbit-two"/><div className="orbit orbit-three"/><Icon name="database" size={76}/></div><div className="auth-shell"><Logo/><div className="auth-card"><span className="preview-label">FOUNDATION PREVIEW · 0.1.0</span><h1>{setup ? 'Your images.\nYour archive.' : 'Welcome back.'}</h1><p>{setup ? 'A modern home for your imaging data. Create your administrator account to get started.' : 'Sign in to your EASI Store imaging archive.'}</p><form onSubmit={submit}><label>Username<input autoFocus autoComplete="username" value={username} onChange={event => setUsername(event.target.value)} required maxLength={80} placeholder="Your administrator username" disabled={busy}/></label><label>Password<input type="password" autoComplete={setup ? 'new-password' : 'current-password'} value={password} onChange={event => setPassword(event.target.value)} required minLength={setup ? 12 : undefined} maxLength={256} placeholder={setup ? 'At least 12 characters' : 'Your password'} disabled={busy}/></label>{setup && <label>Confirm password<input type="password" autoComplete="new-password" value={confirm} onChange={event => setConfirm(event.target.value)} required minLength={12} maxLength={256} placeholder="Enter your password again" disabled={busy}/></label>}{setup && session.bootstrapRequired && <label>Server setup code<input autoComplete="off" value={bootstrapToken} onChange={event => setBootstrapToken(event.target.value)} required placeholder="One-time token from the server" disabled={busy}/><small className="setup-help">For Docker, run docker compose exec store cat /data/bootstrap-token. For other deployments, read bootstrap-token in the archive data directory.</small></label>}{error && <div className="inline-error" role="alert">{error}</div>}<button className="button primary auth-submit" type="submit" disabled={busy}>{busy ? <Spinner/> : <Icon name={setup ? 'arrow' : 'shield'}/>} {setup ? 'Create your archive' : 'Sign in'}</button></form><div className="auth-security"><Icon name="shield" size={16}/><span>{setup ? 'No default passwords. No cloud account. Your server, your data.' : 'Your session stays on this EASI Store server.'}</span></div></div><p className="auth-footnote">Built with EASI JS. Made for the way you work.</p></div></main>;
}

function UploadDialog({ onClose, onComplete }: { onClose: () => void; onComplete: () => void }) {
  const [files, setFiles] = useState<File[]>([]); const [busy, setBusy] = useState(false); const [dragging, setDragging] = useState(false); const [current, setCurrent] = useState(0); const [result, setResult] = useState({ stored: 0, duplicate: 0, failed: 0 }); const [errors, setErrors] = useState<string[]>([]); const [finished, setFinished] = useState(false);
  const fileInput = useRef<HTMLInputElement>(null); const folderInput = useRef<HTMLInputElement>(null); const stop = useRef(false);
  function select(input: FileList | File[]) { if (!busy) { setFiles(Array.from(input).filter(file => file.name !== '.DS_Store' && !file.name.startsWith('._') && file.name.toUpperCase() !== 'DICOMDIR')); setFinished(false); setErrors([]); setResult({ stored: 0, duplicate: 0, failed: 0 }); setCurrent(0); } }
  async function upload() {
    setBusy(true); setErrors([]); stop.current = false; let outcome = { stored: 0, duplicate: 0, failed: 0 };
    for (let i = 0; i < files.length; i++) {
      if (stop.current) break;
      setCurrent(i);
      try { const response = await api('/instances', { method: 'POST', headers: { 'Content-Type': 'application/dicom' }, body: files[i] }); if (response.status === 'duplicate') outcome.duplicate++; else outcome.stored++; }
      catch (e) { outcome.failed++; setErrors(previous => [...previous.slice(-19), `${files[i].name}: ${errorMessage(e)}`]); if ((e as { status?: number }).status === 401) stop.current = true; }
      setResult({ ...outcome }); setCurrent(i + 1);
    }
    setBusy(false); setFinished(true); onComplete();
  }
  const totalBytes = files.reduce((sum, file) => sum + file.size, 0);
  return <Modal title="Import imaging data" eyebrow="ADD TO YOUR ARCHIVE" onClose={onClose} busy={busy} footer={<><span className="subtle">{finished ? `${result.stored} stored · ${result.duplicate} already archived · ${result.failed} failed` : files.length ? `${count(files.length)} files · ${bytes(totalBytes)}` : 'DICOM files, including files with no extension'}</span><div className="button-row">{busy ? <button className="button secondary" onClick={() => { stop.current = true; }}>Stop after current file</button> : <><button className="button secondary" onClick={onClose}>{finished ? 'Done' : 'Cancel'}</button>{!finished && <button className="button primary" disabled={!files.length} onClick={upload}><Icon name="upload" size={17}/> Import {files.length ? count(files.length) : ''} files</button>}</>}</div></>}>
    <div className="upload-notice"><Icon name="info" size={20}/><p>Importing <strong>uploads files to this EASI Store server</strong> and adds them to its archive. Original files on your device are not changed or removed.</p></div>
    <input ref={fileInput} className="visually-hidden" type="file" multiple onChange={event => { if (event.target.files) select(event.target.files); event.target.value = ''; }}/>
    <input ref={folderInput} className="visually-hidden" type="file" multiple {...{ webkitdirectory: '', directory: '' }} onChange={event => { if (event.target.files) select(event.target.files); event.target.value = ''; }}/>
    {!busy && !finished && <div className={`drop-zone ${dragging ? 'dragging' : ''}`} onDragOver={event => { event.preventDefault(); setDragging(true); }} onDragLeave={() => setDragging(false)} onDrop={event => { event.preventDefault(); setDragging(false); select(event.dataTransfer.files); }}><div className="drop-icon"><Icon name="upload" size={30}/></div><h3>{files.length ? `${count(files.length)} files ready to import` : 'Drop DICOM files here'}</h3><p>{files.length ? `${bytes(totalBytes)} will be sent to your archive.` : 'Or choose files or a folder from your device.'}</p><div className="button-row"><button className="button secondary" onClick={() => fileInput.current?.click()}><Icon name="file" size={16}/> Choose files</button><button className="button secondary" onClick={() => folderInput.current?.click()}><Icon name="folder" size={16}/> Choose folder</button></div><small>Folder imports scan the selected files. DICOMDIR indexes and macOS sidecar files are skipped.</small></div>}
    {busy && <div className="import-progress" aria-live="polite"><Spinner/><h3>Archiving your imaging data</h3><p>{count(current)} of {count(files.length)} files processed</p><progress value={current} max={files.length}/><span className="subtle truncate">{files[Math.min(current, files.length - 1)]?.name}</span><small>Each file is saved durably before the server confirms it.</small></div>}
    {finished && <div className={`import-result ${result.failed ? 'has-errors' : ''}`}><div className="result-icon"><Icon name={result.failed ? 'info' : 'check'} size={30}/></div><h3>{stop.current ? 'Import stopped' : result.failed && !result.stored && !result.duplicate ? 'No files were imported' : 'Your archive is up to date'}</h3><p>{count(result.stored)} new instances stored{result.duplicate ? `, ${count(result.duplicate)} duplicates safely skipped` : ''}.{stop.current && ` ${count(files.length - current)} files remain unprocessed.`}</p></div>}
    {!!errors.length && <details className="import-errors" open><summary>{count(result.failed)} files could not be imported</summary><ul>{errors.map((error, index) => <li key={index}>{error}</li>)}</ul>{result.failed > 20 && <p>Showing the last 20 errors.</p>}</details>}
  </Modal>;
}

function ViewerDialog({ request, onClose }: { request: ViewerRequest; onClose: () => void }) {
  const mount = useRef<HTMLDivElement>(null); const viewer = useRef<any>(null); const dialog = useRef<HTMLDivElement>(null); const [index, setIndex] = useState(request.index); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const [loaded, setLoaded] = useState(0); const [ready, setReady] = useState(false);
  const instance = request.instances[index];
  useEffect(() => {
    let disposed = false; let instanceViewer: any;
    async function start() {
      try {
        const sdkUrl = '/vendor/easi-view/1.0.0-rc.1/assets/easi-view.js';
        const sdk = await import(sdkUrl);
        if (disposed) return;
        instanceViewer = sdk.createViewer(mount.current, { initialDemo: null, branding: { name: 'EASI View', showReleaseTag: true }, ui: { library: Boolean(request.wholeSeries), demos: false, inspector: true }, theme: { accent: '#7bdfc4', background: '#090e15', panel: '#0e1721' } });
        viewer.current = instanceViewer;
        instanceViewer.on('error', (event: any) => { if (!disposed) setError(errorMessage(new Error(event?.message || 'The viewer could not complete this display operation.'))); });
        await instanceViewer.ready;
        if (!disposed) setReady(true);
      } catch (e) { if (!disposed) { setError(errorMessage(e)); setLoading(false); } }
    }
    start();
    return () => { disposed = true; instanceViewer?.dispose(); viewer.current = null; };
  }, [request.wholeSeries]);
  useEffect(() => {
    if (!ready) return;
    let cancelled = false; const controller = new AbortController();
    async function open() {
      setLoading(true); setError(''); setLoaded(0);
      try {
        const records = request.wholeSeries ? request.instances : [instance]; const files: File[] = [];
        for (const record of records) {
          const response = await fetch(downloadPath(record), { credentials: 'same-origin', signal: controller.signal });
          if (!response.ok) {
            if (response.status === 401) window.dispatchEvent(new Event('easi-session-expired'));
            throw new Error(`The archived image could not be retrieved (${response.status}).`);
          }
          const blob = await response.blob();
          if (cancelled) return;
          files.push(new File([blob], `${record.id || 'instance'}.dcm`, { type: 'application/dicom' })); setLoaded(files.length);
        }
        await viewer.current?.openFiles(files);
      } catch (e) { if (!cancelled) setError(errorMessage(e)); }
      finally { if (!cancelled) setLoading(false); }
    }
    open();
    return () => { cancelled = true; controller.abort(); };
  }, [ready, index, instance, request.instances, request.wholeSeries]);
  useEffect(() => { const previous = document.activeElement as HTMLElement | null; const overflow = document.body.style.overflow; document.body.style.overflow = 'hidden'; dialog.current?.focus(); const listener = (event: KeyboardEvent) => { if (event.key === 'Escape') onClose(); }; document.addEventListener('keydown', listener); return () => { document.removeEventListener('keydown', listener); document.body.style.overflow = overflow; previous?.focus(); }; }, [onClose]);
  return <div className="viewer-dialog" ref={dialog} tabIndex={-1} role="dialog" aria-modal="true" aria-label="EASI View image viewer"><header className="viewer-host-header"><div className="viewer-title"><span className="viewer-badge">EASI VIEW</span><div><strong>{request.series.seriesDescription || 'Imaging series'}</strong><small>{person(request.study.patientName)} · {date(request.study.studyDate)}</small></div></div><div className="viewer-header-actions">{!request.wholeSeries && <div className="instance-pager"><button className="icon-button" aria-label="Previous instance" disabled={index === 0 || loading} onClick={() => setIndex(value => value - 1)}><Icon name="chevron" className="flipped" size={17}/></button><span>Instance {index + 1} / {count(request.instances.length)}</span><button className="icon-button" aria-label="Next instance" disabled={index + 1 >= request.instances.length || loading} onClick={() => setIndex(value => value + 1)}><Icon name="chevron" size={17}/></button></div>}<button className="button secondary small" onClick={onClose}><Icon name="close" size={16}/> Close viewer</button></div></header><div className="viewer-embed" ref={mount}/>{loading && <div className="viewer-loading" role="status"><Spinner/><span>{request.wholeSeries ? `Loading series · ${loaded}/${request.instances.length} instances` : 'Opening archived image…'}</span></div>}{error && <div className="viewer-host-error" role="alert"><Icon name="info"/><div><strong>This image could not be displayed</strong><p>{error}</p><small>The original is safely archived. Display support depends on the EASI View image profile.</small></div><button className="icon-button" aria-label="Dismiss viewer error" onClick={() => setError('')}><Icon name="close"/></button></div>}</div>;
}

function StudyDetail({ study, onBack, onView }: { study: Study; onBack: () => void; onView: (request: ViewerRequest) => void }) {
  const [series, setSeries] = useState<Series[]>([]); const [selected, setSelected] = useState<Series | null>(null); const [instances, setInstances] = useState<Instance[]>([]); const [loading, setLoading] = useState(true); const [instanceLoading, setInstanceLoading] = useState(false); const [error, setError] = useState(''); const [page, setPage] = useState(0); const seriesRequest = useRef(0);
  useEffect(() => () => { seriesRequest.current++; }, []);
  useEffect(() => { let alive = true; setLoading(true); setError(''); setSelected(null); api<{ items: Series[] }>(`/studies/${encodeURIComponent(study.studyUid)}/series`).then(result => { if (alive) setSeries(result.items); }).catch(e => { if (alive) setError(errorMessage(e)); }).finally(() => { if (alive) setLoading(false); }); return () => { alive = false; }; }, [study.studyUid]);
  async function selectSeries(item: Series) {
    const requestId = ++seriesRequest.current;
    setSelected(item); setInstanceLoading(true); setInstances([]); setError(''); setPage(0);
    try { const result = await api<{ items: Instance[] }>(`/studies/${encodeURIComponent(study.studyUid)}/series/${encodeURIComponent(item.seriesUid)}/instances`); if (requestId === seriesRequest.current) setInstances(result.items); }
    catch (e) { if (requestId === seriesRequest.current) setError(errorMessage(e)); } finally { if (requestId === seriesRequest.current) setInstanceLoading(false); }
  }
  const canOpenSeries = selected && instances.length > 0 && instances.reduce((sum, item) => sum + item.bytes, 0) <= 128 * 1024 * 1024 && instances.reduce((sum, item) => sum + (item.frames || 1), 0) <= 2000;
  return <><button className="back-link" onClick={onBack}><Icon name="arrow" size={17} className="flipped"/> Back to library</button><section className="patient-banner"><div className="patient-avatar"><Icon name="patient" size={26}/></div><div className="patient-banner-name"><h2>{person(study.patientName)}</h2><span>Patient ID <strong>{study.patientId || 'not supplied'}</strong></span></div><span className="outline-pill"><Icon name="database" size={13}/> Archived on this server</span></section><section className="study-detail-heading"><div><span className="eyebrow">EXAMINATION · {date(study.studyDate)}</span><h1>{study.studyDescription || 'Untitled study'}</h1><p>{count(study.seriesCount)} series <span>·</span> {count(study.instanceCount)} instances <span>·</span> {bytes(study.bytes)}</p></div><div className="modality-group">{study.modalities?.map(modality => <span className={`modality modality-${modality.toLowerCase()}`} key={modality}>{modality}</span>)}</div></section>{error && <div className="inline-error" role="alert">{error}</div>}<div className="detail-grid"><section className="series-section"><div className="section-label"><h3>Series</h3><span>{count(series.length)} in this study</span></div>{loading ? <div className="loading-area"><Spinner/><span>Loading series…</span></div> : <div className="series-list">{series.map((item, index) => <button className={`series-card ${selected?.seriesUid === item.seriesUid ? 'selected' : ''}`} key={item.seriesUid} onClick={() => selectSeries(item)}><div className={`series-symbol symbol-${item.modality?.toLowerCase()}`}><Icon name="image" size={24}/><span>{item.modality || 'DICOM'}</span></div><div className="series-copy"><div className="series-number">SERIES {item.seriesNumber || index + 1}</div><strong>{item.seriesDescription || 'Unnamed series'}</strong><small>{count(item.instanceCount)} instances <span>·</span> {bytes(item.bytes)}</small></div><Icon name="chevron" size={17}/></button>)}</div>}</section><section className="instance-section"><div className="section-label"><h3>{selected ? 'Instances' : 'Explore your study'}</h3>{selected && <span>{count(instances.length)} archived</span>}</div>{!selected ? <div className="select-series-empty"><div className="empty-circle"><Icon name="image" size={30}/></div><h3>Every image, in its place.</h3><p>Choose a series to inspect its instances, download an original, or open EASI View.</p><div className="mini-flow"><span>Study</span><Icon name="chevron" size={13}/><span>Series</span><Icon name="chevron" size={13}/><span>Instances</span></div></div> : instanceLoading ? <div className="loading-area"><Spinner/><span>Loading instances…</span></div> : <><div className="instance-toolbar"><div><strong>{selected.seriesDescription || 'Selected series'}</strong><small>Original DICOM objects · unchanged bytes</small></div><button className="button primary small" disabled={!canOpenSeries} title={!canOpenSeries ? 'Open individual instances below. Whole-series preview is limited to 128 MiB and 2,000 frames.' : 'Open this series in EASI View'} onClick={() => onView({ study, series: selected, instances, index: 0, wholeSeries: true })}><Icon name="play" size={15}/> View series</button></div>{!canOpenSeries && instances.length > 0 && <p className="instance-limit-note">Open individual instances below. Whole-series preview is limited to 128 MiB and 2,000 frames.</p>}<div className="instance-table-wrap"><table className="instance-table"><thead><tr><th>Instance</th><th>Dimensions</th><th>Size</th><th><span className="visually-hidden">Actions</span></th></tr></thead><tbody>{instances.slice(page * 25, page * 25 + 25).map((item, localIndex) => <tr key={item.sopUid}><td><button className="instance-open" onClick={() => onView({ study, series: selected, instances, index: page * 25 + localIndex })}><Icon name="image" size={17}/><span>{item.instanceNumber || page * 25 + localIndex + 1}</span>{item.frames > 1 && <small>{count(item.frames)} frames</small>}</button></td><td>{item.columns && item.rows ? `${item.columns} × ${item.rows}` : '—'}</td><td>{bytes(item.bytes)}</td><td className="table-actions"><button className="icon-button" aria-label={`View instance ${item.instanceNumber || page * 25 + localIndex + 1}`} onClick={() => onView({ study, series: selected, instances, index: page * 25 + localIndex })}><Icon name="external" size={16}/></button><a className="icon-button" href={downloadPath(item)} download aria-label={`Download original instance ${item.instanceNumber || page * 25 + localIndex + 1}`}><Icon name="download" size={16}/></a></td></tr>)}</tbody></table></div>{instances.length > 25 && <div className="pagination"><span>{page * 25 + 1}–{Math.min((page + 1) * 25, instances.length)} of {count(instances.length)}</span><div className="button-row"><button className="icon-button" aria-label="Previous instance page" disabled={!page} onClick={() => setPage(value => value - 1)}><Icon name="chevron" className="flipped" size={16}/></button><button className="icon-button" aria-label="Next instance page" disabled={(page + 1) * 25 >= instances.length} onClick={() => setPage(value => value + 1)}><Icon name="chevron" size={16}/></button></div></div>}<p className="source-note"><Icon name="shield" size={14}/> Viewing retrieves original files from your archive. EASI View runs in your browser.</p></>}</section></div><details className="uid-details"><summary>Study identifiers</summary><code>{study.studyUid}</code><p>Patient identity is scoped to its source and issuer. Matching names alone do not merge patients.</p></details></>;
}

function Library({ onImport, onDemo, refresh, summary, onView }: { onImport: () => void; onDemo: () => void; refresh: number; summary: Summary; onView: (request: ViewerRequest) => void }) {
  const [search, setSearch] = useState(''); const [query, setQuery] = useState(''); const [items, setItems] = useState<Study[]>([]); const [total, setTotal] = useState(0); const [offset, setOffset] = useState(0); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const [selected, setSelected] = useState<Study | null>(null);
  useEffect(() => { const timer = setTimeout(() => { setQuery(search); setOffset(0); }, 250); return () => clearTimeout(timer); }, [search]);
  useEffect(() => { const controller = new AbortController(); setLoading(true); setError(''); api<{ items: Study[]; total: number }>(`/studies?search=${encodeURIComponent(query)}&limit=50&offset=${offset}`, { signal: controller.signal }).then(result => { setItems(result.items); setTotal(result.total); }).catch(e => { if (!controller.signal.aborted) setError(errorMessage(e)); }).finally(() => { if (!controller.signal.aborted) setLoading(false); }); return () => controller.abort(); }, [query, offset, refresh]);
  if (selected) return <StudyDetail study={selected} onBack={() => setSelected(null)} onView={onView}/>;
  return <><div className="page-heading"><div><div className="eyebrow">YOUR IMAGING WORKSPACE</div><h1>Study library<span className="title-dot">.</span></h1><p>A clear view of your imaging data. All in one place.</p></div><button className="button primary" onClick={onImport}><Icon name="upload" size={18}/> Import images</button></div><div className="stat-grid">{([{ label: 'Patients', value: summary.patients, icon: 'patient' }, { label: 'Studies', value: summary.studies, icon: 'folder' }, { label: 'Instances', value: summary.instances, icon: 'image' }, { label: 'Original data', value: bytes(summary.bytes), icon: 'database' }] as { label: string; value: number | string; icon: IconName }[]).map((stat, index) => <div className={`stat-card stat-${index}`} key={stat.label}><span className="stat-icon"><Icon name={stat.icon} size={19}/></span><div className="stat-value">{typeof stat.value === 'number' ? count(stat.value) : stat.value}</div><div className="stat-label">{stat.label}</div>{index === 3 && <span className="stat-note">Preserved without modification</span>}</div>)}</div><section className="library-panel"><div className="library-toolbar"><div className="search-box"><Icon name="search" size={18}/><input aria-label="Search patients or studies" placeholder="Search patients, patient IDs, or studies…" value={search} onChange={event => setSearch(event.target.value)}/>{search && <button className="icon-button" aria-label="Clear search" onClick={() => setSearch('')}><Icon name="close" size={15}/></button>}</div><span className="library-count">{count(total)} {total === 1 ? 'study' : 'studies'}</span><span className="outline-pill server-pill"><span className="status-dot"/> This archive</span></div>{error && <div className="inline-error" role="alert">{error}</div>}{loading ? <div className="loading-area"><Spinner/><span>Loading your library…</span></div> : !items.length ? <div className="library-empty"><div className="empty-illustration" aria-hidden="true"><div className="illustration-back"/><div className="illustration-front"><Icon name="image" size={42}/><span className="illustration-line"/><span className="illustration-line short"/></div><span className="illustration-plus">+</span></div><span className="eyebrow">{query ? 'NO MATCHING STUDIES' : 'A FRESH START'}</span><h2>{query ? 'Let’s try another search.' : 'Make room for a better archive.'}</h2><p>{query ? 'Search by patient name, patient ID, or study description.' : 'Import your first DICOM files, or explore with a safely generated synthetic study. Your images deserve a clear home.'}</p><div className="button-row">{query ? <button className="button secondary" onClick={() => setSearch('')}>Clear search</button> : <><button className="button primary" onClick={onImport}><Icon name="upload" size={17}/> Import DICOM files</button><button className="button secondary" onClick={onDemo}><Icon name="spark" size={17}/> Try a synthetic study</button></>}</div>{!query && <div className="empty-facts"><span><Icon name="shield" size={14}/> Your server, your data</span><span><Icon name="check" size={14}/> Original bytes preserved</span><span><Icon name="connections" size={14}/> DICOMweb ready</span></div>}</div> : <><div className="study-table-wrap"><table className="study-table"><thead><tr><th>Patient</th><th>Study / examination</th><th>Date</th><th>Modality</th><th>Images</th><th aria-label="Open"/></tr></thead><tbody>{items.map(study => <tr key={study.studyUid} onClick={() => setSelected(study)}><td><button className="patient-link" onClick={event => { event.stopPropagation(); setSelected(study); }}><span className="table-avatar">{person(study.patientName).charAt(0).toUpperCase()}</span><span><strong>{person(study.patientName)}</strong><small>ID {study.patientId || 'not supplied'}</small></span></button></td><td><strong className="study-description">{study.studyDescription || 'Untitled study'}</strong><small className="cell-secondary">{count(study.seriesCount)} {study.seriesCount === 1 ? 'series' : 'series'}</small></td><td className="date-cell">{date(study.studyDate)}</td><td><div className="modality-group">{(study.modalities || []).map(modality => <span key={modality} className={`modality modality-${modality.toLowerCase()}`}>{modality}</span>)}</div></td><td><span className="image-count">{count(study.instanceCount)}</span><small className="cell-secondary">{bytes(study.bytes)}</small></td><td><Icon name="chevron" size={17}/></td></tr>)}</tbody></table></div><div className="pagination"><span>Showing {offset + 1}–{Math.min(offset + items.length, total)} of {count(total)} studies</span><div className="button-row"><button className="button secondary small" disabled={!offset} onClick={() => setOffset(value => Math.max(0, value - 50))}>Previous</button><button className="button secondary small" disabled={offset + items.length >= total} onClick={() => setOffset(value => value + 50)}>Next</button></div></div></>}</section><section className="library-bottom"><div className="pipeline-note"><div className="pipeline-symbol"><Icon name="connections" size={23}/></div><div><h3>Stream in. Keep originals. Build freely.</h3><p>Powered by EASI JS streaming pipelines, with DICOMweb for your applications and EASI View for your images.</p></div></div><span className="small-label">INDEPENDENT BY DESIGN</span></section></>;
}

function Activity({ refresh }: { refresh: number }) {
  const [items, setItems] = useState<any[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const [tick, setTick] = useState(0);
  useEffect(() => { let alive = true; setLoading(true); api<{ items: any[] }>('/activity').then(result => { if (alive) setItems(result.items); }).catch(e => { if (alive) setError(errorMessage(e)); }).finally(() => { if (alive) setLoading(false); }); return () => { alive = false; }; }, [refresh, tick]);
  return <><div className="page-heading"><div><div className="eyebrow">KNOW WHAT HAPPENED</div><h1>Archive activity<span className="title-dot">.</span></h1><p>A persisted record of successful imports and duplicate detections.</p></div><button className="button secondary" onClick={() => setTick(value => value + 1)} disabled={loading}><Icon name="refresh" size={17}/> Refresh</button></div><section className="content-panel activity-panel"><div className="section-label"><h3>Recent archive events</h3><span>Latest 100 events</span></div>{error && <div className="inline-error" role="alert">{error}</div>}{loading ? <div className="loading-area"><Spinner/><span>Loading activity…</span></div> : !items.length ? <div className="small-empty"><div className="empty-circle"><Icon name="activity" size={30}/></div><h3>A clean slate.</h3><p>Import activity will appear here as you add files to your archive.</p></div> : <ol className="activity-list">{items.map((item, index) => { const status = item.status || item.outcome || item.type || 'stored'; const duplicate = /duplicate/i.test(status); const failed = /fail|error/i.test(status); const time = item.createdAt || item.timestamp || item.created_at || item.at; return <li key={item.id || index}><span className={`event-icon ${failed ? 'warning' : duplicate ? 'duplicate' : ''}`}><Icon name={failed ? 'info' : duplicate ? 'copy' : 'check'} size={17}/></span><div className="event-copy"><strong>{duplicate ? 'Duplicate safely skipped' : failed ? 'Import could not be completed' : 'DICOM instance archived'}</strong><p>{item.message || (duplicate ? 'An identical original is already in this archive.' : 'The original object and catalog entry have been saved durably.')}</p><div className="event-meta"><span>{item.source || 'Import'}</span>{item.bytes ? <span>{bytes(item.bytes)}</span> : null}{item.sopUid || item.instanceId ? <code title={item.sopUid || item.instanceId}>{String(item.sopUid || item.instanceId).slice(-18)}</code> : null}</div></div>{time && <time dateTime={time}>{new Date(time).toLocaleString()}</time>}</li>; })}</ol>}</section></>;
}

function Connections({ capabilities }: { capabilities: any }) {
  const [copied, setCopied] = useState(''); const [checking, setChecking] = useState(false); const [status, setStatus] = useState(''); const [error, setError] = useState('');
  async function copy(value: string) { try { await navigator.clipboard.writeText(value); setCopied(value); setTimeout(() => setCopied(''), 2500); } catch { setError('Clipboard access is unavailable. Select and copy the endpoint text below.'); } }
  async function test() { setChecking(true); setError(''); setStatus(''); try { const response = await fetch('/dicomweb/studies?limit=1', { credentials: 'same-origin', headers: { Accept: 'application/dicom+json' } }); if (!response.ok) throw new Error(`The DICOMweb endpoint returned HTTP ${response.status}.`); const result = await response.json(); if (!Array.isArray(result)) throw new Error('The endpoint did not return a DICOM JSON result list.'); setStatus('Connection verified. QIDO-RS returned a valid DICOM JSON response.'); } catch (e) { setError(errorMessage(e)); } finally { setChecking(false); } }
  const base = `${location.origin}/dicomweb`;
  return <><div className="page-heading"><div><div className="eyebrow">CONNECT YOUR ECOSYSTEM</div><h1>Connections<span className="title-dot">.</span></h1><p>One archive. Open protocols. Your choice of applications.</p></div></div><section className="connection-card"><div className="connection-card-top"><div className="connection-logo"><Icon name="connections" size={27}/></div><div><h2>DICOMweb</h2><p>The primary HTTP interface to this archive.</p></div><span className="outline-pill"><span className="status-dot"/> Available</span></div><div className="endpoint-row"><span>BASE URL</span><code>{base}</code><button className="icon-button" aria-label="Copy DICOMweb base URL" onClick={() => copy(base)}><Icon name={copied === base ? 'check' : 'copy'} size={17}/></button></div><div className="protocol-grid"><div><span className="protocol-name">QIDO-RS</span><strong>Find imaging data</strong><p>Search studies, series, and instances.</p></div><div><span className="protocol-name">STOW-RS</span><strong>Store original objects</strong><p>Import multipart DICOM into your archive.</p></div><div><span className="protocol-name">WADO-RS</span><strong>Retrieve originals</strong><p>Read unchanged DICOM object bytes.</p></div></div><div className="connection-footer"><span><Icon name="shield" size={15}/> Authentication required. No wildcard CORS.</span><button className="button secondary small" onClick={test} disabled={checking}>{checking ? <Spinner/> : <Icon name="refresh" size={15}/>} Test connection</button></div>{status && <div className="inline-success" role="status"><Icon name="check" size={16}/>{status}</div>}{error && <div className="inline-error" role="alert">{error}</div>}</section><div className="two-columns"><section className="content-panel"><div className="panel-icon"><Icon name="file" size={23}/></div><h3>A clear conformance profile</h3><p>This preview implements the primary original-object workflows. Transcoding, full metadata, frame retrieval, and advanced DICOMweb services are tracked for future phases.</p><details className="capability-details"><summary>Inspect server capabilities</summary><pre>{JSON.stringify(capabilities, null, 2)}</pre></details></section><section className="content-panel"><div className="panel-icon"><Icon name="database" size={23}/></div><h3>DIMSE storage listener</h3><p>{capabilities?.dimse?.enabled ? <>C-ECHO and durable C-STORE are available at <strong className="accent-text">{location.hostname}:{capabilities.dimse.port}</strong>, with called AE title <strong className="accent-text">{capabilities.dimse.aeTitle}</strong>.</> : <>The optional C-ECHO / C-STORE listener is not enabled in this server session. Its availability and configuration are reported in the server capabilities.</>}</p><div className="notice-badge"><Icon name="shield" size={15}/> Trusted local peers only in this preview. DICOM TLS and query/retrieve services are later milestones.</div></section></div></>;
}

function Settings({ capabilities, summary }: { capabilities: any; summary: Summary }) {
  return <><div className="page-heading"><div><div className="eyebrow">A FOUNDATION YOU CAN TRUST</div><h1>About your archive<span className="title-dot">.</span></h1><p>Simple to run. Clear about what is supported.</p></div><span className="preview-label">0.1.0 · PREVIEW</span></div><div className="settings-grid"><section className="content-panel"><h2>Archive foundation</h2><p>Independent EASI Store server, powered by EASI JS streaming pipelines.</p><dl className="settings-list"><div><dt>Catalog</dt><dd>SQLite</dd></div><div><dt>Original object storage</dt><dd>Local filesystem</dd></div><div><dt>Stored instances</dt><dd>{count(summary.instances)}</dd></div><div><dt>Original source data</dt><dd>{bytes(summary.bytes)}</dd></div><div><dt>Original bytes</dt><dd className="accent-text">Preserved · SHA-256 verified on import</dd></div><div><dt>Usage telemetry</dt><dd>None</dd></div></dl></section><section className="content-panel"><h2>Preview scope</h2><p>This is a working foundation release. It is not a qualified production PACS or a claim of full DICOM conformance.</p><ul className="scope-list"><li><Icon name="check" size={16}/> Durable imports and persisted study catalog</li><li><Icon name="check" size={16}/> Primary DICOMweb original-object workflows</li><li><Icon name="check" size={16}/> Embedded independent EASI View SDK</li><li><Icon name="check" size={16}/> Local account authentication</li></ul><p className="small-text">Advanced protocols, production identity, distributed storage, migration tools, and platform-signed installers follow in later phases.</p></section><section className="content-panel license-panel"><div><span className="eyebrow">GENEROUS BY DESIGN</span><h2>Source available.<br/>Built to be useful.</h2><p>The EASI Community License provides eligible research, nonprofit, and small-company use. Commercial licensing applies under the license’s revenue and eligibility terms.</p><p className="small-text">Xinonix Interactive Development, Inc. · Commercial licensing: <a href="mailto:dvaccaro@xinonix.com">dvaccaro@xinonix.com</a></p></div><div className="license-emblem"><Logo compact/></div></section><section className="content-panel"><h3>Server capabilities</h3><p>Capabilities are reported by this running server. Consult the repository’s conformance profile for transaction details and limitations.</p><details className="capability-details"><summary>Show capabilities JSON</summary><pre>{JSON.stringify(capabilities, null, 2)}</pre></details></section></div></>;
}

function App() {
  const importTrigger = useRef<HTMLElement | null>(null); const viewerTrigger = useRef<HTMLElement | null>(null);
  const [session, setSession] = useState<Session | null>(null); const [sessionError, setSessionError] = useState(''); const [page, setPage] = useState<Page>('library'); const [summary, setSummary] = useState<Summary>({ patients: 0, studies: 0, series: 0, instances: 0, bytes: 0 }); const [capabilities, setCapabilities] = useState<any>({}); const [refresh, setRefresh] = useState(0); const [upload, setUpload] = useState(false); const [busy, setBusy] = useState(false); const [toast, setToast] = useState(''); const [error, setError] = useState(''); const [viewerRequest, setViewerRequest] = useState<ViewerRequest | null>(null); const [mobileNav, setMobileNav] = useState(false);
  const loadSession = useCallback(async () => { try { setSessionError(''); setSession(await api<Session>('/session')); } catch (e) { setSessionError(errorMessage(e)); } }, []);
  const update = useCallback(() => setRefresh(value => value + 1), []);
  const openUpload = useCallback(() => { importTrigger.current = document.activeElement as HTMLElement; setUpload(true); }, []);
  const closeUpload = useCallback(() => { setUpload(false); requestAnimationFrame(() => importTrigger.current?.focus()); }, []);
  const openViewer = useCallback((request: ViewerRequest) => { viewerTrigger.current = document.activeElement as HTMLElement; setViewerRequest(request); }, []);
  const closeViewer = useCallback(() => { setViewerRequest(null); requestAnimationFrame(() => viewerTrigger.current?.focus()); }, []);
  useEffect(() => { loadSession(); const listener = () => { setSession({ authenticated: false, setupRequired: false }); setUpload(false); setViewerRequest(null); setError('Your session has expired. Sign in again to continue.'); }; window.addEventListener('easi-session-expired', listener); return () => window.removeEventListener('easi-session-expired', listener); }, [loadSession]);
  useEffect(() => { if (!session?.authenticated) return; let alive = true; Promise.all([api<Summary>('/summary'), api('/capabilities')]).then(([stats, caps]) => { if (alive) { setSummary(stats); setCapabilities(caps); } }).catch(e => { if (alive) setError(errorMessage(e)); }); return () => { alive = false; }; }, [session?.authenticated, refresh]);
  useEffect(() => { if (!toast) return; const timer = setTimeout(() => setToast(''), 5500); return () => clearTimeout(timer); }, [toast]);
  async function demo() { setBusy(true); setError(''); try { await api('/demo', { method: 'POST', body: '{}' }); update(); setPage('library'); setToast('Synthetic study added. Explore the series and open it in EASI View.'); } catch (e) { setError(errorMessage(e)); } finally { setBusy(false); } }
  async function logout() { try { await api('/logout', { method: 'POST', body: '{}' }); setSession({ authenticated: false, setupRequired: false }); setPage('library'); } catch (e) { setError(errorMessage(e)); } }
  if (sessionError) return <main className="connection-error"><Logo/><div className="empty-circle"><Icon name="connections" size={30}/></div><h1>Let’s reconnect.</h1><p>{sessionError}</p><button className="button primary" onClick={loadSession}><Icon name="refresh" size={17}/> Retry connection</button></main>;
  if (!session) return <main className="app-loading"><Logo/><Spinner label="Connecting to your archive"/><p>Connecting to your archive…</p></main>;
  if (!session.authenticated) return <AuthScreen session={session} onAuthenticated={() => { setError(''); loadSession(); }}/>;
  const nav: { id: Page; title: string; icon: IconName }[] = [{ id: 'library', title: 'Study library', icon: 'library' }, { id: 'activity', title: 'Activity', icon: 'activity' }, { id: 'connections', title: 'Connections', icon: 'connections' }, { id: 'settings', title: 'Administration', icon: 'settings' }];
  return <div className="app-shell"><a className="skip-link" href="#main-content">Skip to content</a><aside inert={Boolean(upload || viewerRequest || busy)} className={`sidebar ${mobileNav ? 'mobile-open' : ''}`}><div className="sidebar-brand"><Logo/><span className="sidebar-preview">PREVIEW</span><button className="icon-button mobile-close" aria-label="Close navigation" onClick={() => setMobileNav(false)}><Icon name="close"/></button></div><div className="workspace-switch"><div className="workspace-avatar"><Icon name="database" size={19}/></div><div><strong>My imaging archive</strong><span><span className="status-dot"/> Self hosted</span></div><Icon name="shield" size={16}/></div><div className="nav-label">WORKSPACE</div><nav className="primary-nav" aria-label="Primary navigation">{nav.map(item => <button key={item.id} className={`nav-item ${page === item.id ? 'active' : ''}`} aria-current={page === item.id ? 'page' : undefined} onClick={() => { setPage(item.id); setMobileNav(false); }}><Icon name={item.icon} size={19}/><span>{item.title}</span>{item.id === 'library' && <span className="nav-count">{count(summary.studies)}</span>}</button>)}</nav><div className="sidebar-grow"/><div className="sidebar-callout"><span className="small-label">MEET YOUR NEW ARCHIVE</span><strong>A little data.<br/>A lot of possibility.</strong><p>Explore a generated study.<br/>No real patient data needed.</p><button onClick={demo} disabled={busy}><Icon name="spark" size={15}/> Add synthetic study <Icon name="arrow" size={15}/></button></div><div className="sidebar-storage"><span><Icon name="database" size={15}/> Original data</span><strong>{bytes(summary.bytes)}</strong><div className="storage-rule"/><small>{count(summary.instances)} preserved DICOM instances</small></div><button className="sidebar-account" onClick={logout}><span className="account-avatar"><Icon name="patient" size={16}/></span><span><strong>Administrator</strong><small>Sign out of this archive</small></span><Icon name="logout" size={17}/></button></aside>{mobileNav && <button className="mobile-nav-backdrop" aria-label="Close navigation" onClick={() => setMobileNav(false)}/>}<div className="app-main" inert={Boolean(upload || viewerRequest || busy)}><header className="topbar"><div className="topbar-breadcrumb"><button className="icon-button mobile-menu" aria-label="Open navigation" onClick={() => setMobileNav(true)}><Icon name="menu"/></button><Icon name="database" size={15}/><span>My archive</span><Icon name="chevron" size={12}/><strong>{nav.find(item => item.id === page)?.title}</strong></div><div className="topbar-right"><span className="private-label"><Icon name="shield" size={14}/> Private workspace</span><span className="version-label">v0.1.0</span></div></header><main id="main-content" className="main-content">{error && <div className="global-error" role="alert"><Icon name="info" size={18}/><span>{error}</span><button className="icon-button" aria-label="Dismiss error" onClick={() => setError('')}><Icon name="close" size={17}/></button></div>}{page === 'library' && <Library summary={summary} refresh={refresh} onImport={openUpload} onDemo={demo} onView={openViewer}/>} {page === 'activity' && <Activity refresh={refresh}/>} {page === 'connections' && <Connections capabilities={capabilities}/>} {page === 'settings' && <Settings capabilities={capabilities} summary={summary}/>}</main><footer className="statusbar"><span><span className="status-dot"/> Archive connected</span><span>{count(summary.patients)} patients <span className="status-separator">/</span> {count(summary.studies)} studies <span className="status-separator">/</span> {count(summary.series)} series</span><span className="statusbar-right"><Icon name="shield" size={13}/> Self hosted. No telemetry.</span></footer></div>{toast && <div className="toast" role="status"><Icon name="check" size={18}/><span>{toast}</span><button className="icon-button" aria-label="Dismiss notification" onClick={() => setToast('')}><Icon name="close" size={16}/></button></div>}{busy && <div className="busy-overlay" role="status"><div><Spinner/><strong>Creating a synthetic study…</strong><p>Generating DICOM objects and saving them to your archive.</p></div></div>}{upload && <UploadDialog onClose={closeUpload} onComplete={update}/>} {viewerRequest && <ViewerDialog request={viewerRequest} onClose={closeViewer}/>}</div>;
}

createRoot(document.getElementById('root')!).render(<App/>);
